(()=>{document.getElementById("Contact_form_handler").addEventListener("submit",e=>{e.preventDefault()});let e=document.querySelector(".notice_message");document.getElementById("notice").addEventListener("click",()=>{(e.style.display="none")&&(e.style.display="block",e.classList.add("notice_Animate"))}),document.getElementById("close_notice").addEventListener("click",()=>{e.style.display="none"}),document.querySelectorAll("img").forEach(e=>{e.addEventListener("mousedown",function(e){e.preventDefault()}),e.addEventListener("contextmenu",function(e){e.preventDefault()})}),window.addEventListener("scroll",function(){const e=document.querySelector(".socialIconsHeader");window.scrollY>0?e.classList.add("scroll"):e.classList.remove("scroll")})})();